// SetParentUsers removes all previously related items of the
// user replacing them completely with the passed
// in related items, optionally inserting them as new records.
// Sets o.R.Parent's ParentUsers accordingly.
// Replaces o.R.ParentUsers with related.
// Sets related.R.Parent's ParentUsers accordingly.
func (o *User) SetParentUsers(exec boil.Executor, insert bool, related ...*User) error {
	query := "update \"users\" set \"parent_id\" = null where \"parent_id\" = $1"
	values := []any{o.ID}
	if boil.DebugMode {
		fmt.Fprintln(boil.DebugWriter, query)
		fmt.Fprintln(boil.DebugWriter, values)
	}
	_, err := exec.Exec(query, values...)
	if err != nil {
		return errors.Wrap(err, "failed to remove relationships before set")
	}

	if o.R != nil {
		for _, rel := range o.R.ParentUsers {
			queries.SetScanner(&rel.ParentID, nil)
			if rel.R == nil {
				continue
			}

			rel.R.Parent = nil
		}
		o.R.ParentUsers = nil
	}

	return o.AddParentUsers(exec, insert, related...)
}

// RemoveParentUsers relationships from objects passed in.
// Removes related items from R.ParentUsers (uses pointer comparison, removal does not keep order)
// Sets related.R.Parent.
func (o *User) RemoveParentUsers(exec boil.Executor, related ...*User) error {
	if len(related) == 0 {
		return nil
	}

	var err error
	for _, rel := range related {
		queries.SetScanner(&rel.ParentID, nil)
		if rel.R != nil {
			rel.R.Parent = nil
		}
		if _, err = rel.Update(exec, boil.Whitelist("parent_id")); err != nil {
			return err
		}
	}
	if o.R == nil {
		return nil
	}

	for _, rel := range related {
		for i, ri := range o.R.ParentUsers {
			if rel != ri {
				continue
			}

			ln := len(o.R.ParentUsers)
			if ln > 1 && i < ln-1 {
				o.R.ParentUsers[i] = o.R.ParentUsers[ln-1]
			}
			o.R.ParentUsers = o.R.ParentUsers[:ln-1]
			break
		}
	}

	return nil
}

